第2轮任务所需的全部输入(MODEL_MAP定稿、extend.AI调用姿势、数字拦截要求)均已在上下文中,可直接实现。以下是 `cloudfunctions/aiGateway/` 三个文件的完整代码:

**`cloudfunctions/aiGateway/index.js`**
```javascript
// 食知AI网关:双通道(extend.AI平台模型 / 自备API),密钥只放环境变量
// 依据:第一部分总结报告§四(六功能位定稿)+ 背景调研_模型与平台
const cloud = require('wx-server-sdk')
cloud.init({ env: cloud.DYNAMIC_CURRENT_ENV })

// 需要 wx-server-sdk >= 4.0.1 才提供 cloud.ai()
const ai = cloud.ai()

// ===== 六功能位模型定稿(改这里即全链路生效)=====
// channel: 'extend' = extend.AI平台模型; 'selfhost' = 自备OpenAI兼容端点
const MODEL_MAP = {
  recognize:  { channel: 'extend', model: 'deepseek-flash', thinking: 'off' },
  copy:       { channel: 'extend', model: 'hy3' },
  nutrition:  { channel: 'extend', model: 'hy3' },                          // 只翻译不出数字
  order_fast: { channel: 'extend', model: 'deepseek-flash', thinking: 'off' },
  order_deep: { channel: 'extend', model: 'deepseek-flash', thinking: 'medium' },
  chat:       { channel: 'extend', model: 'deepseek-flash', thinking: 'low' },
}

// thinking档位映射:off -> disabled;low/medium/high -> enabled + effort
function buildThinking(cfg) {
  if (!cfg.thinking) return null
  if (cfg.thinking === 'off') return { type: 'disabled' }
  return { type: 'enabled', effort: cfg.thinking }
}

// 统一提取返回文本(兼容不同返回形态)
function extractText(res) {
  if (!res) return ''
  if (typeof res.text === 'string') return res.text
  return res.choices && res.choices[0] && res.choices[0].message
    ? res.choices[0].message.content || ''
    : ''
}

// ---- extend.AI 通道 ----
// messages 中图片消息形态(与官方教程一致,由调用方构造):
//   { role: 'user', content: [
//       { type: 'text', text: '...' },
//       { type: 'image_url', image_url: { url: 'data:image/jpeg;base64,...' } }
//   ]}
async function callExtend(cfg, messages) {
  const model = ai.createModel('cloudbase')
  const data = { model: cfg.model, messages }
  const thinking = buildThinking(cfg)
  if (thinking) data.thinking = thinking
  return model.generateText(data)
}

// ---- selfhost 备选通道(OpenAI兼容端点,默认关闭:环境变量缺失即不可用)----
async function callSelfhost(cfg, messages) {
  const baseUrl = process.env.SELFHOST_BASE_URL
  const apiKey = process.env.SELFHOST_API_KEY
  if (!baseUrl || !apiKey) {
    throw new Error('selfhost_channel_not_configured')
  }
  const resp = await fetch(baseUrl.replace(/\/$/, '') + '/chat/completions', {
    method: 'POST',
    headers: {
      'Authorization': 'Bearer ' + apiKey,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ model: cfg.model, messages, stream: false }),
  })
  return resp.json()
}

// ---- nutrition 数字泄漏红线:数值必须来自数据库,模型只做翻译 ----
const NUMERIC_LEAK = /\d+(\.\d+)?\s*(kcal|kj|千卡|大卡|千焦|克|毫克|g|mg)/i

exports.main = async (event) => {
  const { mode, messages } = event || {}
  const cfg = MODEL_MAP[mode]
  if (!cfg) return { error: 'unknown_mode', mode }

  let res
  try {
    res = cfg.channel === 'extend'
      ? await callExtend(cfg, messages)
      : await callSelfhost(cfg, messages)
  } catch (e) {
    return { error: 'gateway_call_failed', detail: e.message }
  }

  // 营养模式返回前拦截数字泄漏
  if (mode === 'nutrition' && !event.allowNumbers) {
    const text = extractText(res)
    if (NUMERIC_LEAK.test(text)) {
      return {
        error: 'numeric_leak_blocked',
        note: '营养数值必须来自数据库,模型输出数字被拦截',
      }
    }
  }

  return res
}
```

**`cloudfunctions/aiGateway/config.json`**
```json
{
  "permissions": {
    "openapi": []
  }
}
```

**`cloudfunctions/aiGateway/package.json`**
```json
{
  "name": "aiGateway",
  "version": "1.0.0",
  "description": "食知AI网关云函数:extend.AI为主通道,selfhost为备选",
  "main": "index.js",
  "dependencies": {
    "wx-server-sdk": "~4.0.1"
  }
}
```

实现要点对照:
- 六功能位与定稿表逐项一致(recognize/order_fast 思考off、order_deep 思考medium、chat 思考low、copy/nutrition 用hy3(无thinking字段)。
- 调用姿势按背景调研:cloud.ai() → createModel('cloudbase') → generateText;thinking 按档位映射为 disabled / enabled+effort。
- 图片以 base64(image_url data URL)进 messages,格式在注释中固定。
- nutrition 模式数字泄漏拦截返回 `numeric_leak_blocked`,可通过 `allowNumbers` 放行。
- selfhost 通道代码就位但默认关闭(缺环境变量即抛错),符合"备选、默认走extend"。
- 无 TODO 占位;仅 selfhost 依赖运行时环境变量注入(属部署配置,非代码占位)。

需要我继续第3轮(备选通道完善 + 《网关部署与联调说明.md》),或先处理第1轮所依赖的骨架文件清单,可在收到文件内容后进行。
